{"path": "count_python_lines.py", "content": "import os
import glob

def count_lines_in_file(file_path):
    """统计单个文件的行数"""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            return len(lines)
    except Exception as e:
        print(f"无法读取文件 {file_path}: {e}")
        return 0

def count_all_python_lines(directory='.'):
    """统计目录及其子目录中所有Python文件的总行数"""
    total_lines = 0
    python_files = []

    # 查找所有Python文件
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                file_path = os.path.join(root, file)
                python_files.append(file_path)

    print(f"找到 {len(python_files)} 个Python文件:")

    # 统计每个文件的行数
    for i, file_path in enumerate(python_files, 1):
        lines = count_lines_in_file(file_path)
        total_lines += lines
        print(f"{i:3d}. {file_path}: {lines} 行")

    return total_lines, python_files

if __name__ == "__main__":
    total_lines, python_files = count_all_python_lines()
    print(f"\n总计: {len(python_files)} 个Python文件，共 {total_lines} 行")"}

